def main():
 for slug,plans in PLANS.items():
  sid='hb-c08-'+slug;ep=ROOT/'studio/episodes'/sid;d=yaml.safe_load((ep/'script.yaml').read_text());assert len(plans)==len(d['sentences']);specs={}
  for i,(r,spec) in enumerate(zip(d['sentences'],plans)):
   spec=list(spec)
   for k in(1,3):
    at=r['sv'].lower().find(spec[k].lower())
    if at<0:raise ValueError((sid,i,spec[k]))
    spec[k]=r['sv'][at:at+len(spec[k])]
   key='picture-'+str(i+1).zfill(3);specs[key]=dict(composition=spec[0],nodes=[dict(label=spec[1],icon=spec[2]),dict(label=spec[3],icon=spec[4])],source_sentence_ids=[r['sentence_id']]);r['visual_cue']='Original source-specific pictorial composition '+spec[0]+': '+spec[1]+' / '+spec[3]+'. No new historical claims.'
  (ep/'picture-plan.json').write_text(json.dumps(specs,ensure_ascii=False,indent=2)+'\n');(ep/'script.yaml').write_text(yaml.safe_dump(d,allow_unicode=True,sort_keys=False,width=100));print(sid,len(specs))
if __name__=='__main__':main()
